from z3 import *

marks = [Int(f'm_{i}') for i in range(11)]
s = Solver()

s.add(marks[0] == 0)
for i in range(10):
    s.add(marks[i] < marks[i+1])

distances = []
for i in range(11):
    for j in range(i+1, 11):
        distances.append(marks[j] - marks[i])

for i in range(len(distances)):
    for j in range(i+1, len(distances)):
        s.add(distances[i] != distances[j])

s.add(marks[10] <= 100)

if s.check() == sat:
    m = s.model()
    print([m[marks[i]].as_long() for i in range(11)])
else:
    print("UNSAT")

def is_golomb(ruler):
    diffs = set()
    for i in range(len(ruler)):
        for j in range(i+1, len(ruler)):
            d = ruler[j] - ruler[i]
            if d in diffs:
                return False
            diffs.add(d)
    return True

r1 = [0, 1, 4, 13, 28, 33, 47, 54, 64, 70, 72]
r2 = [0, 2, 8, 18, 25, 39, 44, 59, 68, 71, 72]

print("r1:", is_golomb(r1))
print("r2:", is_golomb(r2))
